        /// <summary>Append state <paramref name="index"/>'s JSON object.</summary>
        public static void WriteState(IObjectResolver c, int index, StringBuilder b)
        {
            switch (index)
            {
                case 0: Write(b, c.Resolve<RelicSite>()); break;
                case 1: Write(b, c.Resolve<CharacterSheet>()); break;
                case 2: Write(b, c.Resolve<FlowState>()); break;
                case 3: Write(b, c.Resolve<LoadingState>()); break;
                case 4: Write(b, c.Resolve<RangeState>()); break;
                case 5: Write(b, c.Resolve<StationState>()); break;
                case 6: Write(b, c.Resolve<CombatState>()); break;
                case 7: Write(b, c.Resolve<EncounterState>()); break;
                case 8: Write(b, c.Resolve<PlayerInventory>()); break;
                case 9: Write(b, c.Resolve<JobBoard>()); break;
                case 10: Write(b, c.Resolve<PlayerJob>()); break;
                case 11: Write(b, c.Resolve<FlightState>()); break;
                case 12: Write(b, c.Resolve<MapState>()); break;
                case 13: Write(b, c.Resolve<LandingSite>()); break;
                case 14: Write(b, c.Resolve<PlayerShip>()); break;
                case 15: Write(b, c.Resolve<PlayerHealth>()); break;
                case 16: Write(b, c.Resolve<PlayerControl>()); break;
                case 17: Write(b, c.Resolve<ShipPicker>()); break;
                case 18: Write(b, c.Resolve<PlayerVoyage>()); break;
                case 19: Write(b, c.Resolve<SaveSlots>()); break;
                case 20: Write(b, c.Resolve<GameSettings>()); break;
                case 21: Write(b, c.Resolve<DiceState>()); break;
                case 22: Write(b, c.Resolve<UniverseState>()); break;
                case 23: Write(b, c.Resolve<Outfitter>()); break;
            }
        }

        /// <summary>Publish a page-sent event. False if it isn't an inbound (ln.web) event.</summary>
        public static bool Publish(IObjectResolver c, string name, Dictionary<string, object> o)
        {
            switch (name)
            {
                case "DevWarpRequested":
                    c.Resolve<IPublisher<DevWarpRequested>>().Publish(new DevWarpRequested(Json.Get(o, "to") as string ?? ""));
                    return true;
                case "CharacterSheetReady":
                    c.Resolve<IPublisher<CharacterSheetReady>>().Publish(new CharacterSheetReady(Json.Get(o, "on") is bool characterSheetReadyOn && characterSheetReadyOn));
                    return true;
                case "CharacterSetupDone":
                    c.Resolve<IPublisher<CharacterSetupDone>>().Publish(new CharacterSetupDone());
                    return true;
                case "CharacterAbilityAdjustRequested":
                    c.Resolve<IPublisher<CharacterAbilityAdjustRequested>>().Publish(new CharacterAbilityAdjustRequested((int)Json.Number(Json.Get(o, "index")), (int)Json.Number(Json.Get(o, "delta"))));
                    return true;
                case "CharacterClassRequested":
                    c.Resolve<IPublisher<CharacterClassRequested>>().Publish(new CharacterClassRequested(Json.Get(o, "id") as string ?? ""));
                    return true;
                case "CharacterOriginRequested":
                    c.Resolve<IPublisher<CharacterOriginRequested>>().Publish(new CharacterOriginRequested(Json.Get(o, "id") as string ?? ""));
                    return true;
                case "CharacterResetRequested":
                    c.Resolve<IPublisher<CharacterResetRequested>>().Publish(new CharacterResetRequested());
                    return true;
                case "CharacterCallsignRequested":
                    c.Resolve<IPublisher<CharacterCallsignRequested>>().Publish(new CharacterCallsignRequested(Json.Get(o, "callsign") as string ?? ""));
                    return true;
                case "SceneChangeRequested":
                    c.Resolve<IPublisher<SceneChangeRequested>>().Publish(new SceneChangeRequested(GameSceneParse(Json.Get(o, "target"))));
                    return true;
                case "RangeResetRequested":
                    c.Resolve<IPublisher<RangeResetRequested>>().Publish(new RangeResetRequested());
                    return true;
                case "StationCallAnswered":
                    c.Resolve<IPublisher<StationCallAnswered>>().Publish(new StationCallAnswered());
                    return true;
                case "StationPlanRequested":
                    c.Resolve<IPublisher<StationPlanRequested>>().Publish(new StationPlanRequested(Json.Get(o, "plan") as string ?? ""));
                    return true;
                case "PsxModeRequested":
                    c.Resolve<IPublisher<PsxModeRequested>>().Publish(new PsxModeRequested(Json.Get(o, "on") is bool psxModeRequestedOn && psxModeRequestedOn));
                    return true;
                case "StationLightsRequested":
                    c.Resolve<IPublisher<StationLightsRequested>>().Publish(new StationLightsRequested(StationLightModeParse(Json.Get(o, "mode"))));
                    return true;
                case "EncounterChoice":
                    c.Resolve<IPublisher<EncounterChoice>>().Publish(new EncounterChoice(Json.Get(o, "option") as string ?? ""));
                    return true;
                case "InputActionPerformed":
                    c.Resolve<IPublisher<InputActionPerformed>>().Publish(new InputActionPerformed(InputActionParse(Json.Get(o, "action"))));
                    return true;
                case "InventoryEquipRequested":
                    c.Resolve<IPublisher<InventoryEquipRequested>>().Publish(new InventoryEquipRequested((int)Json.Number(Json.Get(o, "uid"))));
                    return true;
                case "InventoryUnequipRequested":
                    c.Resolve<IPublisher<InventoryUnequipRequested>>().Publish(new InventoryUnequipRequested((int)Json.Number(Json.Get(o, "slot"))));
                    return true;
                case "InventoryMoveRequested":
                    c.Resolve<IPublisher<InventoryMoveRequested>>().Publish(new InventoryMoveRequested((int)Json.Number(Json.Get(o, "uid")), (int)Json.Number(Json.Get(o, "x")), (int)Json.Number(Json.Get(o, "y")), (int)Json.Number(Json.Get(o, "rot"))));
                    return true;
                case "InventoryUseRequested":
                    c.Resolve<IPublisher<InventoryUseRequested>>().Publish(new InventoryUseRequested((int)Json.Number(Json.Get(o, "uid"))));
                    return true;
                case "InventoryDropRequested":
                    c.Resolve<IPublisher<InventoryDropRequested>>().Publish(new InventoryDropRequested((int)Json.Number(Json.Get(o, "uid"))));
                    return true;
                case "JobAcceptRequested":
                    c.Resolve<IPublisher<JobAcceptRequested>>().Publish(new JobAcceptRequested((int)Json.Number(Json.Get(o, "index"))));
                    return true;
                case "FlightHudReady":
                    c.Resolve<IPublisher<FlightHudReady>>().Publish(new FlightHudReady(Json.Get(o, "on") is bool flightHudReadyOn && flightHudReadyOn));
                    return true;
                case "ShipPickerReady":
                    c.Resolve<IPublisher<ShipPickerReady>>().Publish(new ShipPickerReady(Json.Get(o, "on") is bool shipPickerReadyOn && shipPickerReadyOn));
                    return true;
                case "ShipSkinStepRequested":
                    c.Resolve<IPublisher<ShipSkinStepRequested>>().Publish(new ShipSkinStepRequested((int)Json.Number(Json.Get(o, "step"))));
                    return true;
                case "ShipPickDone":
                    c.Resolve<IPublisher<ShipPickDone>>().Publish(new ShipPickDone());
                    return true;
                case "SaveSlotsReady":
                    c.Resolve<IPublisher<SaveSlotsReady>>().Publish(new SaveSlotsReady(Json.Get(o, "on") is bool saveSlotsReadyOn && saveSlotsReadyOn));
                    return true;
                case "SaveSlotPicked":
                    c.Resolve<IPublisher<SaveSlotPicked>>().Publish(new SaveSlotPicked((int)Json.Number(Json.Get(o, "index"))));
                    return true;
                case "SaveSlotDeleteRequested":
                    c.Resolve<IPublisher<SaveSlotDeleteRequested>>().Publish(new SaveSlotDeleteRequested((int)Json.Number(Json.Get(o, "index"))));
                    return true;
                case "MenuItemSelected":
                    c.Resolve<IPublisher<MenuItemSelected>>().Publish(new MenuItemSelected(MenuActionParse(Json.Get(o, "action"))));
                    return true;
                case "UniverseSelected":
                    c.Resolve<IPublisher<UniverseSelected>>().Publish(new UniverseSelected(Json.Get(o, "id") as string ?? "", (int)Json.Number(Json.Get(o, "step"))));
                    return true;
                case "UpgradeBuyRequested":
                    c.Resolve<IPublisher<UpgradeBuyRequested>>().Publish(new UpgradeBuyRequested(Json.Get(o, "id") as string ?? ""));
                    return true;
                case "OutfitterCloseRequested":
                    c.Resolve<IPublisher<OutfitterCloseRequested>>().Publish(new OutfitterCloseRequested());
                    return true;
                default:
                    return false;
            }
        }

        static void Write(StringBuilder b, RelicSite s)
        {
            b.Append('{');
            b.Append("\"lying\":");
            Json.Num(b, s.Lying.Value);
            b.Append(",\"reveal\":");
            Json.Str(b, s.Reveal.Value);
            b.Append('}');
        }

