        static string GameSceneName(GameScene v)
        {
            switch (v)
            {
                case GameScene.Unspecified: return "Unspecified";
                case GameScene.Title: return "Title";
                case GameScene.Intro: return "Intro";
                case GameScene.Planet: return "Planet";
                case GameScene.Station: return "Station";
                case GameScene.FlightSchool: return "FlightSchool";
                case GameScene.Orbit: return "Orbit";
                case GameScene.Hold: return "Hold";
