        static void ControlLockNames(StringBuilder b, ControlLock v)
        {
            b.Append('[');
            var first = true;
            if ((v & ControlLock.Spawn) != 0)
            {
                if (!first) b.Append(',');
                first = false;
                Json.Str(b, "Spawn");
            }
            if ((v & ControlLock.Vehicle) != 0)
            {
                if (!first) b.Append(',');
                first = false;
                Json.Str(b, "Vehicle");
            }
            if ((v & ControlLock.Map) != 0)
            {
                if (!first) b.Append(',');
                first = false;
                Json.Str(b, "Map");
            }
            if ((v & ControlLock.Encounter) != 0)
            {
                if (!first) b.Append(',');
                first = false;
                Json.Str(b, "Encounter");
            }
            if ((v & ControlLock.Downed) != 0)
            {
                if (!first) b.Append(',');
                first = false;
                Json.Str(b, "Downed");
            }
            if ((v & ControlLock.Leaving) != 0)
            {
                if (!first) b.Append(',');
                first = false;
                Json.Str(b, "Leaving");
            }
            b.Append(']');
        }

